private boolean complete;

public NoiseHandshake(boolean initiator, NoiseKeyPair staticKey, RelayProtocol.Route route) {
    this(initiator, staticKey, null, route);
}

NoiseHandshake(boolean initiator, NoiseKeyPair staticKey, NoiseKeyPair ephemeralKey,
               RelayProtocol.Route route) {
    this.initiator = initiator;
    try {
        state = new HandshakeState(RelayProtocol.NOISE_SUITE,
                initiator ? HandshakeState.INITIATOR : HandshakeState.RESPONDER);
        state.getLocalKeyPair().setPrivateKey(staticKey.privateKey(), 0);
        if (ephemeralKey != null) {
            state.getFixedEphemeralKey().setPrivateKey(ephemeralKey.privateKey(), 0);
        }
        byte[] prologue = prologue(route);
        state.setPrologue(prologue, 0, prologue.length);
        state.start();
